mapper.select:
SELECT a.id, a.eir_id, a.plate_no, a.appt_date, a.time_slot, a.status, a.driver_id, a.create_time,
       e.eir_no AS eirNo, e.business_type AS businessType, e.container_no AS containerNo,
       e.company_id AS companyId, c.name AS companyName,
       d.name AS driverName
FROM appointment a
LEFT JOIN eir_order e ON e.id = a.eir_id
LEFT JOIN transport_company c ON c.id = e.company_id
LEFT JOIN driver d ON d.id = a.driver_id


        AND e.eir_no LIKE CONCAT('%', #{eirNo}, '%')


        AND a.driver_id = #{driverId}


        AND a.status = #{status}


        AND e.company_id = #{companyId}


        AND a.appt_date = #{apptDate}


ORDER BY a.appt_date DESC, a.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM appointment a
LEFT JOIN eir_order e ON e.id = a.eir_id


        AND e.eir_no LIKE CONCAT('%', #{eirNo}, '%')


        AND a.driver_id = #{driverId}


        AND a.status = #{status}


        AND e.company_id = #{companyId}


        AND a.appt_date = #{apptDate}
